<div class="page-heading admin-heading"><div><a class="back-link" href="<?= url('admin/support') ?>">← Support queue</a><span class="eyebrow"><?= e($ticket['ticket_number']) ?></span><h1><?= e($ticket['subject']) ?></h1><p><?= e($ticket['applicant_name']) ?> · <?= e($ticket['email']) ?> · <?= e($ticket['mobile']) ?></p></div><span class="status-pill status-<?= e($ticket['status']) ?> large"><?= e(ucwords(str_replace('_',' ',$ticket['status']))) ?></span></div><div class="support-admin-layout"><section class="card conversation"><div class="conversation-head"><span>Category: <b><?= e(ucfirst($ticket['category'])) ?></b></span><span>Priority: <b><?= e(ucfirst($ticket['priority'])) ?></b></span><span>Opened: <b><?= format_date($ticket['created_at'],true) ?></b></span></div><?php foreach($messages as $message):?><article class="<?= $message['is_staff_reply']?'staff':'' ?>"><span class="initial-avatar"><?= e(strtoupper(substr($message['sender_name'],0,1))) ?></span><div><header><b><?= e($message['sender_name']) ?></b><small><?= $message['is_staff_reply']?'College staff':'Applicant' ?> · <?= format_date($message['created_at'],true) ?></small></header><p><?= nl2br(e($message['message'])) ?></p></div></article><?php endforeach?></section><aside class="card ticket-reply"><span class="eyebrow">Respond</span><h2>Reply to applicant</h2><form method="post" action="<?= url('admin/support/'.$ticket['id'].'/reply') ?>"><?= csrf_field() ?><label><span>Message</span><textarea name="message" rows="9" required placeholder="Write a clear, helpful response…"></textarea></label><label><span>Set ticket status</span><select name="status"><option value="in_progress">In progress</option><option value="resolved">Resolved</option><option value="open">Open</option><option value="closed">Closed</option></select></label><button class="button button-primary button-block">Send reply & notify →</button></form><p>Reply actions and status changes are written to the audit trail.</p></aside></div>
